//! Generated by Codex. Aggregate Wasm allocation accounting per Store.

use super::invocation_limits::InvocationLimits;
use wasmtime::{ResourceLimiter, StoreLimits, StoreLimitsBuilder};

pub(crate) struct InvocationMemory {
    inner: StoreLimits,
    bytes: usize,
    elements: usize,
    max_bytes: usize,
    max_elements: usize,
}
impl InvocationMemory {
    pub(crate) fn new(limits: &InvocationLimits) -> Self {
        Self {
            inner: StoreLimitsBuilder::new()
                .instances(128)
                .memories(16)
                .tables(16)
                .build(),
            bytes: 0,
            elements: 0,
            max_bytes: limits.memory_bytes,
            max_elements: limits.table_elements,
        }
    }
}
impl ResourceLimiter for InvocationMemory {
    fn memory_growing(
        &mut self,
        current: usize,
        desired: usize,
        maximum: Option<usize>,
    ) -> wasmtime::Result<bool> {
        let delta = desired.saturating_sub(current);
        if delta > self.max_bytes.saturating_sub(self.bytes) {
            return Err(wasmtime::Error::msg(
                "procedure linear-memory budget exhausted",
            ));
        }
        if maximum.is_some_and(|max| desired > max) {
            return Ok(false);
        }
        self.bytes += delta;
        Ok(true)
    }
    fn memory_grow_failed(&mut self, error: wasmtime::Error) -> wasmtime::Result<()> {
        // Trap instead of trying to reuse accounting after allocator failure.
        Err(error)
    }
    fn table_growing(
        &mut self,
        current: usize,
        desired: usize,
        maximum: Option<usize>,
    ) -> wasmtime::Result<bool> {
        let delta = desired.saturating_sub(current);
        if delta > self.max_elements.saturating_sub(self.elements) {
            return Err(wasmtime::Error::msg("procedure table budget exhausted"));
        }
        if maximum.is_some_and(|max| desired > max) {
            return Ok(false);
        }
        self.elements += delta;
        Ok(true)
    }
    fn table_grow_failed(&mut self, error: wasmtime::Error) -> wasmtime::Result<()> {
        Err(error)
    }
    fn instances(&self) -> usize {
        self.inner.instances()
    }
    fn tables(&self) -> usize {
        self.inner.tables()
    }
    fn memories(&self) -> usize {
        self.inner.memories()
    }
}
